CREATE TABLE ezcontentobject_attribute (id SERIAL NOT NULL, version INT DEFAULT 0 NOT NULL, attribute_original_id INT DEFAULT 0, contentclassattribute_id INT DEFAULT 0 NOT NULL, contentobject_id INT DEFAULT 0 NOT NULL, data_float DOUBLE PRECISION DEFAULT NULL, data_int INT DEFAULT NULL, data_text TEXT DEFAULT NULL, data_type_string VARCHAR(50) DEFAULT '', language_code VARCHAR(20) DEFAULT '' NOT NULL, language_id BIGINT DEFAULT 0 NOT NULL, sort_key_int INT DEFAULT 0 NOT NULL, sort_key_string VARCHAR(255) DEFAULT '' NOT NULL, PRIMARY KEY(id, version));
